"""Group actions on forms and on separator variables (general)."""
import sys, struct
sys.path.insert(0, "<HOME>/c72_indep/y22/src")
from codes import *
from autgroup import apply_perm
from linalg import Elim


def enumerate_group(gens, n):
    """All elements (tuples p, p[i] = image of i) of the group generated by gens."""
    def compose(p, q):
        return tuple(p[q[i]] for i in range(n))
    idp = tuple(range(n))
    seen = {idp}
    fr = [idp]
    gens = [tuple(g) for g in gens]
    while fr:
        nf = []
        for h in fr:
            for g in gens:
                x = compose(g, h)
                if x not in seen:
                    seen.add(x)
                    nf.append(x)
        fr = nf
    return sorted(seen)


def form_image(P, M, p):
    """Gram matrix of B^g, B^g(x,y) = B(gx, gy), in the basis P.G."""
    k = P.k
    gG = [apply_perm(g, p, P.n) for g in P.G]
    out = [0] * k
    for i in range(k):
        for j in range(k):
            if P.B(M, gG[i], gG[j]):
                out[i] |= 1 << j
    return out


def write_action(P, xpairs, perms, path):
    """xpairs: list of (y, x) defining the separator variables phi_i = B(y_i, x_i) (independent mod diag).
    For each g: phi_i(B^g) = B(g y_i, g x_i) = sum_j M_ij phi_j(B) + c_i. Writes binary action file."""
    FS = P.FS
    nd = len(P.diag)
    E = Elim()
    for t, (f, c) in enumerate(P.diag):
        E.add(f, 1 << t)
    for i, (y, x) in enumerate(xpairs):
        ok, _ = E.add(FS.functional(y, x), 1 << (nd + i))
        assert ok, "separator functionals not independent"
    diag_const = sum(1 << t for t, (f, c) in enumerate(P.diag) if c)
    nx = len(xpairs)
    wordset = P.wordset
    with open(path, "wb") as f:
        f.write(struct.pack("<ii", len(perms), nx))
        for p in perms:
            const = 0
            rows = []
            for i, (y, x) in enumerate(xpairs):
                gy, gx = apply_perm(y, p, P.n), apply_perm(x, p, P.n)
                assert gy in wordset and gx in wordset
                combo, resid = E.express(FS.functional(gy, gx))
                assert resid == 0, "image not in separator span (separator not invariant)"
                rows.append(combo >> nd)
                if bin(combo & diag_const & ((1 << nd) - 1)).count("1") & 1:
                    const |= 1 << i
            for r in rows:
                f.write(struct.pack("<Q", r))
            f.write(struct.pack("<Q", const))
